% Workloads for the clause-storage benchmarks (#1019). The fact tables t/2 (static), dt/2 (dynamic) and step/2
% (static) are generated by TheorySolverBenchmark: t(I, J) and dt(I, J) with J = 10000 - I, step(I, I + 1).

% fact-table-arg0 / fact-table-arg1 / dynamic-table-arg0: N lookups bound on one argument of a 10k-fact table
lookup_arg0(N, N) :- !.
lookup_arg0(I, N) :- t(I, _), I1 is I + 1, lookup_arg0(I1, N).
lookup_arg1(N, N) :- !.
lookup_arg1(I, N) :- t(_, I), I1 is I + 1, lookup_arg1(I1, N).
lookup_dynamic(N, N) :- !.
lookup_dynamic(I, N) :- dt(I, _), I1 is I + 1, lookup_dynamic(I1, N).

% dynamic-counter: the most common dynamic-database idiom, a counter updated N times
counter(N) :- retractall(cnt(_)), assertz(cnt(0)), count_up(N).
count_up(N) :- cnt(N), !.
count_up(N) :- retract(cnt(C)), C1 is C + 1, assertz(cnt(C1)), count_up(N).

% dynamic-churn: N assertions of a fresh fact, each retracted right away
churn(N, N) :- !.
churn(I, N) :- assertz(k(I)), retract(k(I)), I1 is I + 1, churn(I1, N).

% determinism: a walk along a 1000-clause chain, deterministic by first-argument indexing
walk(1000).
walk(N) :- step(N, M), walk(M).
